function Greeting({ name }) {
  return <p>Hello, {name}!</p>;
}

export default function App() {
  return <Greeting name="Ama" />;
}

function Progress({ completed, total }) {
  return <p>{completed} of {total} lessons completed</p>;
}

export default function App() {
  return <Progress completed={4} total={10} />;
}

function Badge({ label, tone = "blue" }) {
  return <span className={`badge badge-${tone}`}>{label}</span>;
}

export default function App() {
  return <Badge label="Beginner" />;
}

function CourseTitle({ course }) {
  return <h2>{course.title}</h2>;
}

export default function App() {
  return <CourseTitle course={{ title: "Python Basics" }} />;
}
